fields.InputDefinition:
{
  "goal": "You are logged in at http://localhost:4200. Open the Permissions app via the application switcher dropdown next to the logo, then click 'Resource Access' in the left nav. Pages can take 10-30s to load — wait, don't navigate away. The surface shows a 'Domain:' dropdown, a 'Resource Type:' combobox, and a 'Resource ID:' text input. Then walk these behaviors IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) domain-switch-populates-types — open the 'Domain:' dropdown and select a different permission domain, and confirm the 'Resource Type:' combobox reacts — its selectable options update to that domain's resource types (open it to confirm, or note it auto-fills a single type) and any now-invalid prior value is cleared; (2) lookup-requires-type-and-id — leaving at least one of 'Resource Type:' or 'Resource ID:' blank, click the 'Lookup' button and confirm the lookup is BLOCKED with a validation error stating that resource type and resource ID are both required (no grantee results table appears); (3) lookup-shows-grantees — now pick a Domain, choose or type a Resource Type, enter any plausible UUID-shaped identifier in 'Resource ID:', and click 'Lookup', then confirm the query RUNS and shows either a grantee table (Grantee / Type / Actions / Effect / Expires columns) with a count OR a clearly labeled 'No grantees found' empty-state echoing the query. Keep going until all three behaviors are done.",
  "startUrl": "http://localhost:4200/app/permissions",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "domain-switch-populates-types",
      "instruction": "Domain change repopulates Resource Type combobox",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/permissions"
        }
      ],
      "visualCriteria": [
        "The Resource Access surface renders with Domain dropdown, Resource Type combobox, and Resource ID input, and changing the Domain selection updates the Resource Type combobox options (or auto-selects a single type / clears a now-invalid prior value)"
      ]
    },
    {
      "name": "lookup-requires-type-and-id",
      "instruction": "Required-field guard blocks empty lookup",
      "visualCriteria": [
        "Clicking 'Lookup' with a blank Resource Type and/or Resource ID surfaces a validation error message indicating both fields are required, and no grantee results table is shown"
      ]
    },
    {
      "name": "lookup-shows-grantees",
      "instruction": "Grantee-resolution lookup runs",
      "visualCriteria": [
        "After entering a domain, resource type, and resource ID and clicking Lookup, the surface shows either a grantee table (Grantee / Type / Actions / Effect / Expires columns) with a count OR a clearly labeled 'No grantees found' empty-state referencing the query"
      ]
    }
  ]
}
